"use client";

import { useCallback, useEffect, useState } from "react";
import Link from "next/link";
import { auth } from "@/firebase";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";

const initial = { title: "", slug: "", description: "", thumbnail: "", instructorName: "", intendedLevel: "", learningObjective: "", bundleUrl: "", durationMinutes: "", relatedTopics: "", publishedAt: "", status: "draft", lessonsJson: "[]", supportingFilesJson: "[]" };

export default function AdminVideoBundlesPage() {
  const [bundles, setBundles] = useState([]);
  const [form, setForm] = useState(initial);
  const [editingId, setEditingId] = useState(null);
  const [message, setMessage] = useState("");
  const [saving, setSaving] = useState(false);
  const request = useCallback(async (options = {}) => { const token = await auth.currentUser?.getIdToken(); return fetch("/api/admin/video-bundles", { ...options, headers: { ...(options.headers || {}), Authorization: `Bearer ${token}` }, cache: "no-store" }); }, []);
  const load = useCallback(async () => { const response = await request(); const result = await response.json().catch(() => []); if (!response.ok) throw new Error(result.error || "Video bundles could not be loaded"); setBundles(result); }, [request]);
  useEffect(() => { const unsubscribe = auth.onAuthStateChanged(() => load().catch((error) => setMessage(error.message))); return unsubscribe; }, [load]);
  const edit = (bundle) => { setEditingId(bundle.id); setForm({ ...initial, ...bundle, publishedAt: bundle.publishedAt ? new Date(bundle.publishedAt).toISOString().slice(0, 16) : "", relatedTopics: (bundle.relatedTopics || []).join(", "), lessonsJson: JSON.stringify(bundle.lessons || [], null, 2), supportingFilesJson: JSON.stringify(bundle.supportingFiles || [], null, 2) }); };
  const save = async () => { setSaving(true); setMessage(""); try { let lessons; let supportingFiles; try { lessons = JSON.parse(form.lessonsJson || "[]"); supportingFiles = JSON.parse(form.supportingFilesJson || "[]"); } catch { throw new Error("Lesson and supporting-file fields must be valid JSON."); } const payload = { ...form, id: editingId, durationMinutes: Number(form.durationMinutes) || 0, relatedTopics: form.relatedTopics.split(",").map((value) => value.trim()).filter(Boolean), lessons, supportingFiles }; delete payload.lessonsJson; delete payload.supportingFilesJson; const response = await request({ method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }); const result = await response.json().catch(() => ({})); if (!response.ok) throw new Error(result.error || "Video bundle could not be saved"); setForm(initial); setEditingId(null); setMessage("Video bundle saved."); await load(); } catch (error) { setMessage(error.message); } finally { setSaving(false); } };
  const field = (name, label, type = "text") => <div><label className="mb-1 block text-sm font-medium">{label}</label><Input type={type} value={form[name] ?? ""} onChange={(event) => setForm((current) => ({ ...current, [name]: event.target.value }))} /></div>;
  return <div className="space-y-8"><div><h1 className="text-3xl font-bold">Video Bundles</h1><p className="mt-2 text-muted-foreground">GO stores protected external links only. It does not upload, stream, or synchronize permissions.</p></div><Card><CardHeader><CardTitle>{editingId ? "Edit video bundle" : "Create video bundle"}</CardTitle></CardHeader><CardContent className="space-y-5"><div className="grid gap-4 md:grid-cols-2">{field("title", "Title")}{field("slug", "Slug")}{field("instructorName", "Instructor / speaker")}{field("intendedLevel", "Intended level")}{field("thumbnail", "Public thumbnail HTTPS URL")}{field("bundleUrl", "Protected complete-bundle HTTPS URL")}{field("durationMinutes", "Duration (minutes)", "number")}{field("publishedAt", "Publication date", "datetime-local")}{field("relatedTopics", "Related topics (comma separated)")}</div><div><label className="mb-1 block text-sm font-medium">Description</label><textarea className="min-h-28 w-full rounded-md border bg-background px-3 py-2" value={form.description} onChange={(event) => setForm((current) => ({ ...current, description: event.target.value }))} /></div><div><label className="mb-1 block text-sm font-medium">Learning objective</label><textarea className="min-h-24 w-full rounded-md border bg-background px-3 py-2" value={form.learningObjective} onChange={(event) => setForm((current) => ({ ...current, learningObjective: event.target.value }))} /></div><div><label className="mb-1 block text-sm font-medium">Ordered lessons (JSON)</label><textarea className="min-h-44 w-full rounded-md border bg-background px-3 py-2 font-mono text-sm" value={form.lessonsJson} onChange={(event) => setForm((current) => ({ ...current, lessonsJson: event.target.value }))} /><p className="mt-1 text-xs text-muted-foreground">Each lesson supports title, description, durationMinutes, and protected externalUrl.</p></div><div><label className="mb-1 block text-sm font-medium">Supporting files (JSON)</label><textarea className="min-h-36 w-full rounded-md border bg-background px-3 py-2 font-mono text-sm" value={form.supportingFilesJson} onChange={(event) => setForm((current) => ({ ...current, supportingFilesJson: event.target.value }))} /></div><div><label className="mb-1 block text-sm font-medium">Status</label><select className="rounded-md border bg-background px-3 py-2" value={form.status} onChange={(event) => setForm((current) => ({ ...current, status: event.target.value }))}><option value="draft">Draft</option><option value="published">Published</option><option value="archived">Archived</option></select></div><div className="flex gap-3"><Button onClick={save} disabled={saving}>{saving ? "Saving..." : "Save video bundle"}</Button>{editingId && <Button variant="outline" onClick={() => { setEditingId(null); setForm(initial); }}>Cancel edit</Button>}</div>{message && <p className="text-sm" role="status">{message}</p>}</CardContent></Card><Card><CardHeader><CardTitle>Bundles</CardTitle></CardHeader><CardContent className="space-y-3">{bundles.map((bundle) => <div key={bundle.id} className="flex flex-wrap items-center justify-between gap-3 rounded-md border p-4"><div><div className="flex items-center gap-2"><p className="font-semibold">{bundle.title}</p><Badge>{bundle.status}</Badge></div><p className="mt-1 text-sm text-muted-foreground">{bundle.lessons?.length || 0} lessons · Community entitlement</p></div><div className="flex gap-2"><Button variant="outline" onClick={() => edit(bundle)}>Edit</Button>{bundle.status === "published" && <Button asChild variant="outline"><Link href={`/video-bundles/${bundle.slug}`}>View</Link></Button>}</div></div>)}{bundles.length === 0 && <p className="py-8 text-center text-muted-foreground">No video bundles have been created.</p>}</CardContent></Card></div>;
}
